# nothing is stored. Every save is audited, even of the value already in force.
validate:
  class: net.officefloor.hq.app.setting.ValidateSettings
  next: apply
  govern: [ transaction ]
apply:
  class: net.officefloor.hq.app.setting.ApplySettings
  next: audit
  govern: [ transaction ]
audit:
  class: net.officefloor.hq.app.setting.AuditSettingChanged
  next: respond
  govern: [ transaction ]
respond:
  class: net.officefloor.hq.app.setting.RespondWithSettings
  govern: [ transaction ]
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

/** `clerkLimit` has two decimals ("1.50"), or is "" when there is no limit. */
export type Settings = { clerkLimit: string };

export type RoleName = 'clerk' | 'steward';

/** The role a sheet gives a user name; a name with no entry is a clerk. */
export type Role = { user: string; role: RoleName };

export const ROLES: RoleName[] = ['clerk', 'steward'];

/** Under the sheet's key, so re-loading the sheet re-reads its settings and roles. */
export const settingsKey = (sheetId: string) => [...sheetKey(sheetId), 'settings'] as const;
export const rolesKey = (sheetId: string) => [...sheetKey(sheetId), 'roles'] as const;

export const settingsQuery = (sheetId: string) => ({
  queryKey: settingsKey(sheetId),
  queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
});

export const rolesQuery = (sheetId: string) => ({
  queryKey: rolesKey(sheetId),
  queryFn: () => getJson<Role[]>(`/api/sheets/${encodeURIComponent(sheetId)}/roles`),
});
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { useUser } from '../session/useUser';
import { ROLES, rolesKey, rolesQuery, settingsKey, settingsQuery } from './settingsQuery';
import type { Role, RoleName, Settings as SheetSettings } from './settingsQuery';

const AMOUNT = /^\d{1,9}(\.\d{1,2})?$/;

/** The sheet's settings — the clerk limit a clerk may settle up to (blank: no limit) — and the
 *  form they are saved through. */
function Settings({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const settings = useQuery(settingsQuery(sheetId));
  const [limit, setLimit] = useState('');
  const [error, setError] = useState('');

  const [user] = useUser();
  const once = useSubmitOnce();
  const save = useMutation({
    mutationFn: (body: SheetSettings) =>
      putJson<SheetSettings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) });
      setLimit('');
    },
    onError: () => setError('The settings could not be saved.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const l = limit.trim();
    if (l !== '' && !AMOUNT.test(l)) {
      setError('The clerk limit must be an amount of 0.00 or more, with up to two decimals.');
      return;
    }
    once(() => save.mutateAsync({ clerkLimit: l }));
  };

  return (
    <section data-testid="settings">
      <h3>Settings</h3>
      <form data-testid="settings-form" onSubmit={submit}>
        <label>
          Clerk limit{' '}
          <input
            data-testid="setting-clerk-limit"
            placeholder="no limit"
            value={limit}
            onChange={(e) => {
              setLimit(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {error && <p data-testid="settings-error">{error}</p>}
      </form>
      {settings.isError && <p data-testid="settings-load-error">Could not load the settings.</p>}
      <p>
        Clerk limit in force: <span data-testid="setting-clerk-limit-current">{settings.data?.clerkLimit ?? ''}</span>
      </p>
    </section>
  );
}

/** The roles the sheet gives user names (any name not listed is a clerk), and the form a role is
 *  set through. */
function Roles({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const roles = useQuery(rolesQuery(sheetId));
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [error, setError] = useState('');

  const [user] = useUser();
  const once = useSubmitOnce();
  const save = useMutation({
    mutationFn: (body: Role) =>
      putJson<Role>(
        `/api/sheets/${encodeURIComponent(sheetId)}/roles/${encodeURIComponent(body.user)}`,
        { role: body.role },
        user,
      ),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: rolesKey(sheetId) });
      setName('');
      setRole('');
    },
    onError: () => setError('The role could not be set.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const n = name.trim();
    const r = role.trim();
    if (n === '') {
      setError('A user name is needed.');
      return;
    }
    if (!ROLES.includes(r as RoleName)) {
      setError('The role must be clerk or steward.');
      return;
    }
    once(() => save.mutateAsync({ user: n, role: r as RoleName }));
  };

  return (
    <section data-testid="roles">
      <h3>Roles</h3>
      <form data-testid="role-form" onSubmit={submit}>
        <label>
          User{' '}
          <input
            data-testid="role-form-user"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <label>
          Role{' '}
          <input
            data-testid="role-form-role"
            placeholder="clerk or steward"
            list="role-names"
            value={role}
            onChange={(e) => {
              setRole(e.target.value);
              setError('');
            }}
          />
          <datalist id="role-names">
            {ROLES.map((r) => (
              <option key={r} value={r} />
            ))}
          </datalist>
        </label>{' '}
        <button type="submit" data-testid="role-form-submit" disabled={save.isPending}>
          Set role
        </button>
        {error && <p data-testid="role-form-error">{error}</p>}
      </form>
      {roles.isError && <p data-testid="roles-load-error">Could not load the roles.</p>}
      <table data-testid="roles-list">
        <tbody>
          {(roles.data ?? []).map((r) => (
            <tr key={r.user} data-testid={`role-row-${r.user}`}>
              <td data-testid="role-user">{r.user}</td>
              <td data-testid="role-value">{r.role}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

// Keyed by sheet, so a typed value or an error never carries over to another sheet.
export const contribution = SheetPanel.fill({
  order: 6,
  Component: ({ sheetId }) => (
    <>
      <Settings key={`settings-${sheetId}`} sheetId={sheetId} />
      <Roles key={`roles-${sheetId}`} sheetId={sheetId} />
    </>
  ),
});

