package net.officefloor.hq.app.statement;

import java.sql.Date;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The store of statements, kept per sheet. */
@Repository
public class Statements {

    private final JdbcTemplate jdbc;

    public Statements(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Locks the person's row until the transaction commits, so two statements of them are taken one after the other. */
    public void lock(long personId) {
        jdbc.queryForList("SELECT id FROM person WHERE id = ? FOR UPDATE", personId);
    }

    public void add(Statement statement) {
        jdbc.update("INSERT INTO statement (sheet_id, person_id, due_total, claims, stated_on) VALUES (?, ?, ?, ?, ?)",
                statement.sheetId(), statement.personId(), statement.dueTotal(), statement.claims(),
                Date.valueOf(statement.statedOn()));
    }

    /** Each person of the sheet who has a statement: their count, and their last statement's due-total and date. */
    public List<StatementResponse> list(String sheetId) {
        return jdbc.query("SELECT s.person_id, c.n, s.due_total, s.stated_on FROM statement s "
                + "JOIN (SELECT person_id, COUNT(*) AS n, MAX(id) AS last_id FROM statement WHERE sheet_id = ? "
                + "GROUP BY person_id) c ON s.id = c.last_id ORDER BY s.person_id",
                (rs, n) -> new StatementResponse(rs.getLong(1), rs.getInt(2), rs.getString(3),
                        rs.getDate(4).toLocalDate().toString()),
                sheetId);
    }

    public StatementResponse find(String sheetId, long personId) {
        return list(sheetId).stream().filter(s -> s.personId() == personId).findFirst()
                .orElse(new StatementResponse(personId, 0, null, null));
    }
}
import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery, counts } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { peopleQuery } from '../people/peopleQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import type { Person } from '../people/peopleQuery';
import { figure, rateFor, ratesQuery, sumDue } from './ratesQuery';
import type { Rate } from './ratesQuery';

/**
 * A person's due-total: the sum of their counting claims' rounded figures, as each claim shows it. With no rate today and no figure it is n/a; otherwise it is the sum of the figures there are.
 */
function personDue(person: Person | undefined, people: Person[], claims: Claim[], rates: Rate[], today: string): string {
  if (!person) return 'n/a';
  const rate = rateFor(rates, person.grade, today);
  const figures = claims
    .filter((c) => c.personId === person.id && counts(c, people))
    .map((c) => figure(c, rates, person.grade))
    .filter((d) => d !== 'n/a');
  return rate === undefined && figures.length === 0 ? 'n/a' : sumDue(figures);
}

function useSheetData(sheetId: string) {
  return {
    people: useQuery(peopleQuery(sheetId)).data ?? [],
    claims: useQuery(claimsQuery(sheetId)).data ?? [],
    rates: useQuery(ratesQuery(sheetId)).data ?? [],
    today: useSheetToday(sheetId),
  };
}

function ClaimDue({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const { people, rates } = useSheetData(sheetId);
  const person = people.find((p) => p.id === claim.personId);
  return <td data-testid="claim-due">{figure(claim, rates, person?.grade)}</td>;
}

function PersonDueTotal({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today } = useSheetData(sheetId);
  return <td data-testid="person-due-total">{personDue(people.find((p) => p.id === personId), people, claims, rates, today)}</td>;
}

function DueTotal({ sheetId }: { sheetId: string }) {
  const { people, claims, rates, today } = useSheetData(sheetId);
  return (
    <p data-testid="rollup-due">
      Due total <strong data-testid="rollup-due-total">{sumDue(people.map((p) => personDue(p, people, claims, rates, today)))}</strong>
    </p>
  );
}

export const contributions = [
  ClaimCells.fill({ order: 10, Component: ClaimDue }),
  PersonHeaders.fill({ order: 15, Component: () => <th>Due</th> }),
  PersonCells.fill({ order: 15, Component: PersonDueTotal }),
  SheetPanel.fill({ order: 25, Component: DueTotal }),
];
